-- ============================================================
-- PlantAssure Iteration 2 backend database seed
-- ============================================================
-- Source: species_data_i2.sql supplied by the data team.
--
-- Backend-owned schema changes:
--   1. Adds stable numeric `id` primary key used as API `plantId`.
--   2. Preserves all 777 Iteration 1 plant IDs by matching exact
--      scientific_name; the 103 new Iteration 2 records use IDs 778-880.
--   3. Keeps `match_key` NON-UNIQUE because Iteration 2 contains
--      subspecies/variety rows that intentionally share a match key.
--   4. Uses table name `species_data` so the existing MyBatis-Plus
--      Entity/Mapper and Iteration 1 endpoints remain compatible.
--   5. Retains alternatives_json for data traceability, but Iteration 2
--      backend business logic does NOT use it as the authoritative
--      alternative result because it may include NOT_ASSESSED plants.
--
-- IMPORTANT:
--   * `risk_rating = 'Not Assessed / No exact match'` is interpreted by
--     backend code as NOT_ASSESSED, never as low concern.
--   * Legal/regulatory classification is not present in this dataset;
--     backend returns legalStatus = UNAVAILABLE in Iteration 2.
-- ============================================================

DROP TABLE IF EXISTS `species_data`;

CREATE TABLE `species_data` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'Stable backend plantId',
  `scientific_name` VARCHAR(150) NOT NULL,
  `vernacular_name` VARCHAR(200) NULL,
  `family` VARCHAR(50) NULL,
  `establishment_means` VARCHAR(30) NULL,
  `degree_of_establishment` VARCHAR(30) NULL,
  `match_key` VARCHAR(150) NULL,
  `risk_rating` VARCHAR(50) NULL,
  `growth_form` VARCHAR(100) NULL,
  `woodiness` VARCHAR(50) NULL,
  `life_history` VARCHAR(100) NULL,
  `height_min` FLOAT NULL,
  `height_max` FLOAT NULL,
  `griis_listed` TINYINT(1) NULL,
  `griis_is_invasive` TINYINT(1) NULL,
  `vba100_record_count` INT NULL,
  `vba100_most_recent_year` SMALLINT UNSIGNED NULL,
  `ala_record_count` INT NULL,
  `ala_most_recent_date` DATE NULL,
  `recommendation` VARCHAR(30) NULL COMMENT 'Pipeline value retained for traceability; backend recalculates recommendation',
  `alternatives_json` TEXT NULL COMMENT 'Pipeline candidate output retained for traceability; backend revalidates alternatives',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_species_data_scientific_name` (`scientific_name`),
  KEY `idx_species_data_match_key` (`match_key`),
  KEY `idx_species_data_risk_rating` (`risk_rating`),
  KEY `idx_species_data_origin` (`establishment_means`),
  KEY `idx_species_data_growth_form` (`growth_form`),
  KEY `idx_species_data_life_history` (`life_history`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

